const fs = require('fs');
const path = require('path');

const defaults = { port: 3000, host: '127.0.0.1' };
const inFile = path.join(__dirname, 'config.json');
const outFile = path.join(__dirname, 'config.out.json');

let config = {};
try {
  config = JSON.parse(fs.readFileSync(inFile, 'utf8'));
} catch (err) {
  config = {};
}

for (const [key, value] of Object.entries(defaults)) {
  if (config[key] === undefined) {
    config[key] = value;
  }
}

fs.writeFileSync(outFile, JSON.stringify(config, null, 2) + '\n');
console.log(`wrote ${outFile}`);

